import { Component, ElementRef, OnDestroy, ViewChild } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { GestureService, GestureStatus } from '../../gesture/gesture.service';
import {
  DEFAULT_GESTURE_ACTIONS,
  GestureAction,
  GestureSettings,
  GestureType,
  HandGesture,
} from '../../gesture/gestures';

interface GestureLog {
  type: GestureType;
  label: string;
  time: string;
}

@Component({
  selector: 'app-gesture-nav',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './gesture-nav.component.html',
  styleUrls: ['./gesture-nav.component.css'],
})
export class GestureNavComponent implements OnDestroy {
  @ViewChild('video') videoRef!: ElementRef<HTMLVideoElement>;
  @ViewChild('canvas') canvasRef!: ElementRef<HTMLCanvasElement>;

  readonly GestureType = GestureType;
  enabled = false;
  status: GestureStatus = 'idle';
  error = '';
  current: HandGesture | null = null;
  lastLabel = '';
  flash = false;
  history: GestureLog[] = [];
  settings: GestureSettings = {
    holdFrames: 3,
    cooldownMs: 1200,
    swipeThreshold: 0.22,
    sound: true,
  };

  actions: GestureAction[] = DEFAULT_GESTURE_ACTIONS;

  private subs: Subscription[] = [];
  private audioCtx: AudioContext | null = null;

  constructor(private gesture: GestureService, private router: Router) {
    this.subs.push(
      this.gesture.status$.subscribe((s) => {
        this.status = s;
        this.enabled = s === 'running';
      })
    );
    this.subs.push(this.gesture.error$.subscribe((e) => (this.error = e)));
    this.subs.push(this.gesture.settings$.subscribe((s) => (this.settings = s)));
    this.subs.push(
      this.gesture.gesture$.subscribe((g) => {
        this.current = g;
        this.onRecognized(g);
      })
    );
  }

  async toggle(): Promise<void> {
    this.error = '';
    if (this.enabled) {
      this.gesture.stop();
      return;
    }
    await this.gesture.start(this.videoRef.nativeElement, this.canvasRef.nativeElement);
  }

  private onRecognized(g: HandGesture): void {
    const action = this.actions.find((a) => a.gesture === g.type);
    if (!action) {
      return;
    }
    this.lastLabel = action.label ?? g.type;
    this.pushHistory(g.type, this.lastLabel);
    this.triggerFlash();
    if (this.settings.sound) {
      this.beep();
    }

    if (action.back) {
      window.history.back();
    } else if (action.forward) {
      window.history.forward();
    } else if (action.scroll) {
      window.scrollBy({ top: action.scroll * 320, behavior: 'smooth' });
    } else {
      this.router.navigate(action.commands ?? ['/']);
    }
  }

  private pushHistory(type: GestureType, label: string): void {
    const time = new Date().toLocaleTimeString();
    this.history = [{ type, label, time }, ...this.history].slice(0, 6);
  }

  private triggerFlash(): void {
    this.flash = true;
    setTimeout(() => (this.flash = false), 250);
  }

  private beep(): void {
    try {
      this.audioCtx = this.audioCtx ?? new (window.AudioContext || (window as any).webkitAudioContext)();
      const osc = this.audioCtx.createOscillator();
      const gain = this.audioCtx.createGain();
      osc.frequency.value = 660;
      osc.type = 'sine';
      gain.gain.setValueAtTime(0.08, this.audioCtx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, this.audioCtx.currentTime + 0.18);
      osc.connect(gain);
      gain.connect(this.audioCtx.destination);
      osc.start();
      osc.stop(this.audioCtx.currentTime + 0.2);
    } catch {
      /* audio not available */
    }
  }

  updateHold(v: number): void {
    this.gesture.updateSettings({ holdFrames: v });
  }

  updateCooldown(v: number): void {
    this.gesture.updateSettings({ cooldownMs: v });
  }

  updateSwipe(v: number): void {
    this.gesture.updateSettings({ swipeThreshold: v });
  }

  toggleSound(): void {
    this.gesture.updateSettings({ sound: !this.settings.sound });
  }

  gestureLabel(type: GestureType): string {
    return this.actions.find((a) => a.gesture === type)?.label ?? type;
  }

  handLabel(handedness: string): string {
    return handedness === 'Right' ? 'Main droite' : handedness === 'Left' ? 'Main gauche' : handedness;
  }

  ngOnDestroy(): void {
    this.gesture.stop();
    this.subs.forEach((s) => s.unsubscribe());
  }
}
<div class="gesture-nav">
  <button
    class="gesture-toggle"
    [class.active]="enabled"
    (click)="toggle()"
    [attr.aria-pressed]="enabled"
    [title]="enabled ? 'تعطيل التنقّل بالإيماءات' : 'تفعيل التنقّل بالإيماءات'"
  >
    <i class="fa-solid" [class.fa-hand]="!enabled" [class.fa-hand-point-up]="enabled"></i>
    <span class="toggle-text">{{ enabled ? 'الإيماءات مفعّلة' : 'الإيماءات معطّلة' }}</span>
  </button>

  <div class="gesture-panel" [class.flash]="flash" [hidden]="status === 'idle'">
    <div class="camera-wrap">
      <video #video autoplay playsinline muted></video>
      <canvas #canvas width="240" height="180"></canvas>
    </div>

    <div class="status" [ngSwitch]="status">
      <span *ngSwitchCase="'loading'" class="badge loading">جارٍ التهيئة…</span>
      <span *ngSwitchCase="'running'" class="badge live">الكاميرا نشطة</span>
      <span *ngSwitchCase="'error'" class="badge error">{{ error || 'خطأ' }}</span>
      <span *ngSwitchDefault class="badge">غير نشط</span>
    </div>

    <div class="current" *ngIf="current && current.type !== GestureType.NONE">
      <span class="gesture-name">{{ current.type }}</span>
      <span class="hand-badge" *ngIf="current.handedness && current.handedness !== 'Unknown'">
        {{ handLabel(current.handedness) }}
      </span>
      <span class="action-label" *ngIf="lastLabel">→ {{ lastLabel }}</span>
    </div>

    <details class="settings" [open]="false">
      <summary>الإعدادات</summary>
      <label>
        الثبات (إطارات) : <b>{{ settings.holdFrames }}</b>
        <input
          type="range"
          min="1"
          max="8"
          step="1"
          [value]="settings.holdFrames"
          (input)="updateHold(+$any($event.target).value)"
        />
      </label>
      <label>
        فترة التهدئة (ms) : <b>{{ settings.cooldownMs }}</b>
        <input
          type="range"
          min="300"
          max="3000"
          step="100"
          [value]="settings.cooldownMs"
          (input)="updateCooldown(+$any($event.target).value)"
        />
      </label>
      <label>
        حساسية التمرير : <b>{{ settings.swipeThreshold }}</b>
        <input
          type="range"
          min="0.1"
          max="0.5"
          step="0.01"
          [value]="settings.swipeThreshold"
          (input)="updateSwipe(+$any($event.target).value)"
        />
      </label>
      <label class="switch">
        <input type="checkbox" [checked]="settings.sound" (change)="toggleSound()" />
        صوت التأكيد
      </label>
    </details>

    <ul class="legend">
      <li><b>✋ Main ouverte</b> — {{ gestureLabel(GestureType.OPEN_HAND) }}</li>
      <li><b>☝️ Index</b> — {{ gestureLabel(GestureType.POINT) }}</li>
      <li><b>✌️ V</b> — {{ gestureLabel(GestureType.PEACE) }}</li>
      <li><b>👍 Pouce</b> — {{ gestureLabel(GestureType.THUMBS_UP) }}</li>
      <li><b>✊ Poing</b> — {{ gestureLabel(GestureType.FIST) }}</li>
      <li><b>↔️ Swipe</b> — السابق / التالي / التمرير</li>
    </ul>

    <div class="history" *ngIf="history.length">
      <div class="history-title">السجل</div>
      <ul>
        <li *ngFor="let h of history">
          <span class="h-type">{{ h.type }}</span>
          <span class="h-label">{{ h.label }}</span>
          <span class="h-time">{{ h.time }}</span>
        </li>
      </ul>
    </div>
  </div>
</div>
